// @ts-nocheck
import {defineConfig} from "vite";
import react from "@vitejs/plugin-react";

// PWA gaba ɗaya a nan: manifest, service worker da alamomi ana ƙirƙirar su lokacin build.
// Ba sai an ɗora wasu fayilolin PWA daban ba.
const MANIFEST={"name": "LASHA ELITE", "short_name": "Lasha Elite", "description": "Shirya da bin diddigin gasa", "lang": "ha", "dir": "ltr", "id": "./", "start_url": "./", "scope": "./", "display": "standalone", "orientation": "portrait", "background_color": "#10224d", "theme_color": "#10224d", "categories": ["sports"], "icons": [{"src": "icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any"}, {"src": "icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any"}, {"src": "icon-maskable-512.png", "sizes": "512x512", "type": "image/png", "purpose": "maskable"}]};
const SW="const V=\"lasha-elite-v2\";\nself.addEventListener(\"install\",e=>{self.skipWaiting();e.waitUntil(caches.open(V).then(c=>c.add(\"./\")).catch(()=>{}))});\nself.addEventListener(\"activate\",e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==V).map(x=>caches.delete(x)))).then(()=>self.clients.claim()))});\nself.addEventListener(\"fetch\",e=>{const r=e.request;if(r.method!==\"GET\"||new URL(r.url).origin!==location.origin)return;\nif(r.mode===\"navigate\"){e.respondWith(fetch(r).then(x=>{const cp=x.clone();caches.open(V).then(c=>c.put(\"./\",cp));return x}).catch(()=>caches.match(\"./\")));return}\ne.respondWith(caches.match(r).then(h=>h||fetch(r).then(x=>{if(x.ok){const cp=x.clone();caches.open(V).then(c=>c.put(r,cp))}return x})))});\n";
const ICONS={
"icon-192.png": "",
"icon-512.png": "",
"icon-maskable-512.png": "",
"apple-touch-icon.png": ""
};

const pwa=()=>({
  name:"lasha-pwa",
  apply:"build",
  generateBundle(){
    this.emitFile({type:"asset",fileName:"manifest.webmanifest",source:JSON.stringify(MANIFEST)});
    this.emitFile({type:"asset",fileName:"sw.js",source:SW});
    for(const [name,data] of Object.entries(ICONS))this.emitFile({type:"asset",fileName:name,source:Buffer.from(data,"base64")});
  }
});

export default defineConfig({base:"./",plugins:[react(),pwa()]});
